 334: /// Whether `name` can name a saved job; see [`job_name_problem`].
 335: pub fn valid_job_name(name: &str) -> bool {
 336:     job_name_problem(name).is_none()
 337: }
 338: 
 339: /// Why `name` cannot name a saved job, in words, or `None` when it can: 1
 340: /// to 64 letters, digits, `-`, `_` or `.`, not starting with `.`, and not
 341: /// shaped like a run ID (32 lowercase hex digits), so a bare word names
 342: /// one job only (reviews cr-jl3b-1, cr-jl3bfix1-1: every refusal says its
 343: /// own reason).
 344: pub fn job_name_problem(name: &str) -> Option<&'static str> {
 345:     if !(1..=64).contains(&name.len()) {
 346:         return Some("a job name is 1 to 64 characters long");
 347:     }
 348:     if name.starts_with('.') {
 349:         return Some("a job name may not start with `.`");
 350:     }
 351:     if !name
 352:         .chars()
 353:         .all(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.'))
 354:     {
 355:         return Some("a job name is made of letters, digits, `-`, `_` and `.`");
 356:     }
 357:     if name.len() == 32 && name.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')) {
 358:         return Some(
 359:             "32 lowercase hex digits are a run ID's shape, kept for run IDs; choose \
 360:              another name",
 361:         );
 362:     }
 363:     None
 364: }
 365: 
 366: /// Whether a `blit jobs` target names a file: it is a path — it holds a
 367: /// separator (`./job.json`, `/tmp/x.jsonl.gz`). A bare word is a saved
 368: /// job's name or a run ID, whatever files the current folder holds
 369: /// (review cr-jl3b-1).
 370: pub fn names_a_path(target: &str) -> bool {
 371:     target.contains('/') || (cfg!(windows) && target.contains('\\'))
 372: }
 373: 
 374: /// A machine's saved jobs: `<per-user folder>/jobs/saved/<name>.json`, kept
 375: /// until deleted (never pruned).
 376: #[derive(Clone, Debug)]
 377: pub struct SavedJobs {
 378:     dir: PathBuf,
 379: }
 380: 
 381: impl SavedJobs {
 382:     pub fn new(dir: impl Into<PathBuf>) -> Self {
 383:         Self { dir: dir.into() }
